  ('3e46aa49-a7a3-4459-9ea9-71cd98820673', '3d4fa537-9c22-423c-a23c-3a023551b4c1', 4,
   $$[{"domain": "Beweging en wisselwerking", "subdomain": "Kracht en beweging"}]$$::jsonb,
