   $$["akoestische lengte", "frequenties aflezen", "staande golf"]$$::jsonb,
   $$Akoestische lengte van buis 1 bepalen uit de grondtoon- en boventoonfrequenties in figuur 2$$,
   $$natuurkunde-vwo-2023-i-boomwhackers-vraag16.png$$, $$Bepaal de akoestische lengte van buis 1 met behulp van figuur 2. Noteer je antwoord in twee significante cijfers.$$, array['a8a4c874-cde8-42e4-bd78-3f954ebc1a1b','5a36163c-8f7e-406c-91a1-d8b9c7f90002','410927bf-40c8-4dc1-96cb-95bbba423789']::uuid[]),
  ('c14f1f64-b93c-473a-8369-0038fb32c99e', '7c06a42e-ba97-4404-8a91-c00e50d838c6', 17,
   $$[{"domain": "Golven", "subdomain": "Informatieoverdracht"}]$$::jsonb,
